    //获取唯一值  从大到小排序
    export function getUniqueCard(value: number[]) {
        let listNum: number[] = utils.deepCopy(value);
        let tmpList: number[] = [];
        for (let i = 0; i < listNum.length; i++) {
            const element = listNum[i];
            if (tmpList.length > 0) {
                let size = getCardSize(element);
                let find: boolean = false;
                for (let j = 0; j < tmpList.length; j++) {
                    if (getCardSize(tmpList[j]) == size) {
                        find = true;
                        break;
                    }
                }
                if (!find) {
                    tmpList.push(element);
                }
            } else {
                tmpList.push(element);
            }
        }
        return sortCardsBySizeDown(tmpList, tmpList.length);
    }
    //数组[[2,2],[3,3,3]] (从大到小)
    export function getSameCardSizeList(value: number[], keepOrder: boolean = false, select: number[] = [], prevSelected: number[]) {
        if (!keepOrder) {
            let tmpList: number[][] = [];
            let sortValue = sortCardsBySizeDown(value, value.length);
            let uniqueList = getUniqueCard(sortValue);
            let idx: number = 0;
            for (let j = 0; j < uniqueList.length; j++) {
                const d = uniqueList[j];
                let list1: number[] = [];
                for (let i = idx; i < sortValue.length; i++) {
                    if (getCardSize(d) == getCardSize(sortValue[i])) {
                        list1.push(sortValue[i]);
                        if (i == sortValue.length - 1) {
                            tmpList.push(list1);
                        }
                    } else {
                        idx = i;
                        tmpList.push(list1);
                        break;
                    }
                }
            }
            // console.log("tmpList---> ", tmpList);
            return tmpList;
        }
        else {
            return moveSelectedCardsToBack(value, select, prevSelected);
        }

    }

    export function moveSelectedCardsToBack(cards: number[], selected: number[], prevSelected: number[]): number[][] {
        // 1. 先按点数分组（你的原始逻辑）
        let tmpList: number[][] = [];
        let sortValue = sortCardsBySizeDown(cards, cards.length);
        let uniqueList = getUniqueCard(sortValue);
        let idx: number = 0;

        for (let j = 0; j < uniqueList.length; j++) {
            const d = uniqueList[j];
            let list1: number[] = [];
            for (let i = idx; i < sortValue.length; i++) {
                if (getCardSize(d) == getCardSize(sortValue[i])) {
                    list1.push(sortValue[i]);
                    if (i === sortValue.length - 1) {
                        tmpList.push(list1);
                    }
                } else {
                    idx = i;
                    tmpList.push(list1);
                    break;
                }
            }
        }

        // 2. 遍历 tmpList，将 selected 中的牌分组移到后面
        let selectedSet = [...selected];
        let prevSet = [...prevSelected];

        let remain: number[][] = [];
        let prevGroup: number[][] = [];
        let newGroup: number[][] = [];

        for (let group of tmpList) {
            // 判断这一组是否属于 prevSelected
            if (group.every(card => prevSet.includes(card))) {
                prevGroup.push(group);
                continue;
            }

            // 判断这一组是否属于本次新选中
            if (group.every(card => selectedSet.includes(card))) {
                newGroup.push(group);
                continue;
            }

            // 否则归为未选中
            remain.push(group);
        }

        return [...remain, ...prevGroup, ...newGroup];
    }

    export function getCardGroupsByOrder(cards: number[]): number[][] {
        const groupList: number[][] = [];
        let temp: number[] = [];

        for (let i = 0; i < cards.length; i++) {
            const cur = cards[i];
            if (temp.length === 0 || GameLogic.getCardSize(temp[0]) === GameLogic.getCardSize(cur)) {
                temp.push(cur);
            } else {
                groupList.push(temp);
                temp = [cur];
            }
        }

        if (temp.length > 0) {
            groupList.push(temp);
        }

        return groupList;
    }

